/// The generated template of `enc`, if there is one.
pub(crate) fn template(enc: Encoding) -> Option<GenFn> {
    Some(match enc {
        Encoding::Syscall => Syscall,
        Encoding::Break => Break,
        Encoding::Tge => Tge,
        Encoding::Tgeu => Tgeu,
        Encoding::Tlt => Tlt,
        Encoding::Tltu => Tltu,
        Encoding::Teq => Teq,
        Encoding::Tne => Tne,
        Encoding::Teqi => Teqi,
        Encoding::Tnei => Tnei,
        Encoding::Tgei => Tgei,
        Encoding::Tgeiu => Tgeiu,
        Encoding::Tlti => Tlti,
        Encoding::Tltiu => Tltiu,
        Encoding::Cache => Cache,
        Encoding::Sync => Sync,
        Encoding::Mfc0 => Mfc0,
        Encoding::Dmfc0 => Dmfc0,
        Encoding::Mtc0 => Mtc0,
        Encoding::Dmtc0 => Dmtc0,
        Encoding::Tlbwi => Tlbwi,
        Encoding::Tlbwr => Tlbwr,
        Encoding::Tlbr => Tlbr,
        Encoding::Tlbp => Tlbp,
        Encoding::Eret => Eret,
        _ => return None,
    })
}
